pub fn clear_assets() {
    let cache_dir = PROJECT_DIRS.cache_dir();
    let theme_file_name = "themes.bin";
    let syntax_file_name = "syntaxes.bin";
    let metadata_file_name = "metadata.yaml";
    let theme_description = "theme set cache";
    let syntax_description = "syntax set cache";
    let metadata_description = "metadata file";
    let themes_path = cache_dir.join(theme_file_name);
    let syntaxes_path = cache_dir.join(syntax_file_name);
    let metadata_path = cache_dir.join(metadata_file_name);
    let current_version = crate_version!();

    let mut has_theme_cache = fs::metadata(&themes_path)
        .map(|meta| meta.is_file())
        .unwrap_or(false);
    let mut has_syntax_cache = fs::metadata(&syntaxes_path)
        .map(|meta| meta.is_file())
        .unwrap_or(false);
    let mut has_metadata_file = fs::metadata(&metadata_path)
        .map(|meta| meta.is_file())
        .unwrap_or(false);
    let mut metadata_compatible = false;

    if cache_dir.is_dir() {
        if let Ok(entries) = fs::read_dir(cache_dir) {
            for entry in entries.flatten() {
                let name = entry.file_name();
                if name == theme_file_name {
                    has_theme_cache = true;
                } else if name == syntax_file_name {
                    has_syntax_cache = true;
                } else if name == metadata_file_name {
                    has_metadata_file = true;
                }
            }
        }

        match AssetsMetadata::load_from_folder(cache_dir) {
            Ok(Some(metadata)) => {
                has_metadata_file = true;
                metadata_compatible = metadata.is_compatible_with(current_version);
            }
            Ok(None) => {
                metadata_compatible = false;
            }
            Err(_) => {
                metadata_compatible = false;
            }
        }

        if has_theme_cache || has_syntax_cache || has_metadata_file {
            if let Ok(assets) = HighlightingAssets::from_cache(cache_dir) {
                has_syntax_cache = assets
                    .get_syntaxes()
                    .ok()
                    .map(|syntaxes| !syntaxes.is_empty())
                    .unwrap_or(metadata_compatible);
                has_theme_cache = assets.themes().next().is_some();
            }
        }
    }

    let cache_files = [
        (themes_path, theme_description),
        (syntaxes_path, syntax_description),
        (metadata_path, metadata_description),
    ];

    for (path, description) in cache_files {
        print!("Clearing {} ... ", description);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                println!("skipped (not present)");
            }
            Err(err) => {
                println!("could not remove the cache file {:?}: {}", path, err);
            }
            Ok(_) => println!("okay"),
        }
    }
}

pub fn assets_from_cache_or_binary(use_custom_assets: bool) -> Result<HighlightingAssets> {
    let cache_dir = PROJECT_DIRS.cache_dir();
    if let Some(metadata) = AssetsMetadata::load_from_folder(cache_dir)? {
        if !metadata.is_compatible_with(crate_version!()) {
            return Err(format!(
                "The binary caches for the user-customized syntaxes and themes \
                 in '{}' are not compatible with this version of bat ({}). To solve this, \
                 either rebuild the cache (bat cache --build) or remove \
                 the custom syntaxes/themes (bat cache --clear).\n\
                 For more information, see:\n\n  \
                 https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
                cache_dir.to_string_lossy(),
                crate_version!()
            )
            .into());
        }
    }

    let custom_assets = if use_custom_assets {
        HighlightingAssets::from_cache(cache_dir).ok()
    } else {
        None
    };
    Ok(custom_assets.unwrap_or_else(HighlightingAssets::from_binary))
}

const THEME_PREVIEW_DATA: &[u8] = include_bytes!("../../../assets/theme_preview.rs");

#[cfg(feature = "build-assets")]
fn build_assets(matches: &clap::ArgMatches) -> Result<()> {
    let source_dir = matches
        .get_one::<String>("source")
        .map(Path::new)
        .unwrap_or_else(|| PROJECT_DIRS.config_dir());
    let target_dir = matches
        .get_one::<String>("target")
        .map(Path::new)
        .unwrap_or_else(|| PROJECT_DIRS.cache_dir());

    bat::assets::build(
        source_dir,
        !matches.get_flag("blank"),
        matches.get_flag("acknowledgements"),
        target_dir,
        clap::crate_version!(),
    )
}

fn run_cache_subcommand(matches: &clap::ArgMatches) -> Result<()> {
    if matches.get_flag("build") {
        #[cfg(feature = "build-assets")]
        build_assets(matches)?;
        #[cfg(not(feature = "build-assets"))]
        println!("bat has been built without the 'build-assets' feature. The 'cache --build' option is not available.");
    } else if matches.get_flag("clear") {
        clear_assets();
    }

    Ok(())
}

fn get_syntax_mapping_to_paths<'a>(
    mappings: &[(GlobMatcher, MappingTarget<'a>)],
) -> HashMap<&'a str, Vec<String>> {
    let mut map = HashMap::new();
    for mapping in mappings {
        if let (matcher, MappingTarget::MapTo(s)) = mapping {
            let globs = map.entry(*s).or_insert_with(Vec::new);
            globs.push(matcher.glob().glob().into());
        }
    }
    map
}

